#[test]
fn w337_workflow_witnesses_only_for_replay_consumers() {
    use crate::{
        app_server::transcript::journal::source::transcript_from_scan,
        contracts::OperationOwner, domain::{ExchangeId, ExecutionId, SessionId},
    };
    for (kind,n) in [("empty",0),("requests",4096),("parts",256),("noparts",256)] {
        let (session, thread, turn, exec)=(SessionId::from_u128(1), ThreadId::from_u128(2),
            TurnId::from_u128(3), ExecutionId::from_uuid(uuid::Uuid::from_u128(4)));
        let mut records=Vec::new();
        let mut push=|entry|records.push(record(session,Some(exec),thread,turn,records.len() as u64+1,entry));
        push(JournalEntry::TurnOpened(TurnOpened{
            intent:None,task:AgentTask::new("fixture","/synthetic/workspace".into()),
            base_history_revision:0,module_epoch:0,config_snapshot:json!({}),
        }));
        let calls=(0..n).map(|i|ToolCall::new(format!("fixture-workflow-call-{i:04}"),"fixture",json!({}))).collect::<Vec<_>>();
        if kind=="parts" || kind=="noparts" {
            let exchange_id=ExchangeId::from_u128(5);
            let request=CanonicalModelRequest::new(ModelRef::new("fixture","fixture"),vec![]);
            push(JournalEntry::ModelRequestRecorded(ModelRequestRecorded{
                exchange_id,origin:ModelCallOrigin::Direct,owner:OperationOwner::Workflow,request,
            }));
            let parts=if kind=="parts" {
                let mut parts=vec![ContentPart::Text{text:"visible via workflow evidence".into()}];
                parts.extend(calls.iter().cloned().map(|call|ContentPart::ToolCall{call}));
                parts
            } else {vec![]};
            let mut msg=CanonicalMessage::new(MessageRole::Assistant,parts);
            msg.id=crate::domain::MessageId::from_u128(6);
            for (i,part) in msg.parts.iter_mut().enumerate() {part.part_id=PartId::from_u128(100+i as u128);}
            let response=CanonicalModelResponse::new(msg,calls.clone(),FinishReason::ToolCalls);
            push(JournalEntry::ModelResponseRecorded(ModelResponseRecorded{
                exchange_id,outcome:ModelResponseOutcome::Response{response},
            }));
        }
        for call in calls {
            push(JournalEntry::ToolCallRecorded(ToolCallRecorded{call,
                phase:ToolCallRecordPhase::Requested{owner:OperationOwner::Workflow}}));
        }
        let projection=JournalProjection::build(session,records).expect("valid durable reader prefix");
        let mut pass=0;
        crate::w337_alloc::WITNESS_INSERTS.with(|n|n.set(0));
        let (rows,m,end)=crate::w337_alloc::measure(||transcript_from_scan(|visit| {
            pass+=1;
            for record in &projection.records {visit(record.clone())?;}
            if pass==2 {crate::w337_alloc::metadata();}
            Ok(())
        },None).unwrap());
        let inserted=crate::w337_alloc::WITNESS_INSERTS.with(|n|n.get());
        assert_eq!(pass,if n==0 {2}else{4});
        let tools=rows.iter().filter_map(|row|row.tool.as_ref()).collect::<Vec<_>>();
        assert_eq!(tools.len(),n);
        assert!(tools.iter().all(|tool|tool.status=="interrupted"));
        let wire=serde_json::to_vec(&rows).unwrap();
        let materialized=TranscriptReplay::new(&projection.records,0).render(projection.records.iter(),None);
        assert_eq!(wire,serde_json::to_vec(&materialized).unwrap());
        if kind=="parts" {assert!(String::from_utf8_lossy(&wire).contains("visible via workflow evidence"));}
        if let Some(dir)=std::env::var_os("W337_WITNESS_DIR") {
            std::fs::write(std::path::PathBuf::from(dir).join(format!("{kind}.json")),wire).unwrap();
        }
        eprintln!("W337 {kind} {n} {pass} {inserted} {} {} {end}",m.metadata.unwrap(),m.peak);
    }
}
